function expandPathAliases(inputPath) {
  return inputPath.replace(/\$([a-zA-Z_][a-zA-Z0-9_]*)/g, (match, varName) => {
    const alias = PATH_ALIASES[varName.toLowerCase()];
    if (alias) {
      return alias;
    }
    // If alias not found, leave it unchanged
    return match;
  });
}

// SOCKS Proxy Agent for routing API requests through 127.0.0.1:9050
const proxyAgent = new SocksProxyAgent('socks://127.0.0.1:9050');

const defaultLogger = {
  info: console.log,
  warn: console.warn,
  error: console.error,
};

// Initialize SQLite database
let db = null;
function initDatabase() {
  if (db) return db;

  db = new Database(CONFIG.IMAGE_RESULTS_DB);
  db.pragma('journal_mode = WAL');

  // Create table with embeddings
  db.exec(`
    CREATE TABLE IF NOT EXISTS image_results (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      timestamp TEXT NOT NULL,
      status TEXT NOT NULL,
      prompt_name TEXT NOT NULL,
      prompt_text TEXT NOT NULL,
      prompt_embedding BLOB,
      refs TEXT NOT NULL,
      model TEXT,
      width INTEGER,
      height INTEGER,
      filename TEXT,
      error TEXT,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );

    CREATE INDEX IF NOT EXISTS idx_status ON image_results(status);
    CREATE INDEX IF NOT EXISTS idx_prompt_name ON image_results(prompt_name);
    CREATE INDEX IF NOT EXISTS idx_timestamp ON image_results(timestamp);
  `);

  return db;
}

// Generate embedding for text
async function generateEmbedding(text) {
  if (!CONFIG.USE_EMBEDDINGS) return null;

  return new Promise((resolve, reject) => {
    const python = spawn('python3', [CONFIG.EMBEDDING_SCRIPT, text]);
    let stdout = '';
    let stderr = '';

    python.stdout.on('data', (data) => {
      stdout += data.toString();
    });

    python.stderr.on('data', (data) => {
      stderr += data.toString();
    });

    python.on('close', (code) => {
      if (code !== 0) {
        // Silently fail if embeddings not available
        resolve(null);
        return;
      }

      try {
        const embedding = JSON.parse(stdout);
        if (embedding.error) {
          resolve(null);
          return;
        }
        // Convert to Buffer for SQLite BLOB
        const buffer = Buffer.from(new Float32Array(embedding).buffer);
        resolve(buffer);
      } catch (error) {
        resolve(null);
      }
    });
  });
}

class RateLimiter {
  constructor(maxCalls, windowMs) {
    this.maxCalls = maxCalls;
    this.windowMs = windowMs;
    this.callTimestamps = [];
  }

  canMakeCall() {
    const now = Date.now();
    this.callTimestamps = this.callTimestamps.filter((timestamp) => now - timestamp < this.windowMs);
    return this.callTimestamps.length < this.maxCalls;
  }

  recordCall() {
    this.callTimestamps.push(Date.now());
  }

  getNextAvailableTime() {
    if (this.canMakeCall()) return 0;
    const now = Date.now();
    this.callTimestamps = this.callTimestamps.filter((timestamp) => now - timestamp < this.windowMs);
    if (this.callTimestamps.length < this.maxCalls) return 0;
    const oldest = this.callTimestamps[0];
    return this.windowMs - (now - oldest) + 100;
  }
}

class ConcurrencyLimiter extends EventEmitter {
  constructor(maxConcurrent) {
    super();
    this.maxConcurrent = maxConcurrent;
    this.currentCount = 0;
  }

  canStart() {
    return this.currentCount < this.maxConcurrent;
  }

  increment() {
    this.currentCount++;
  }

  decrement() {
    this.currentCount--;
    if (this.currentCount < 0) this.currentCount = 0;
    this.emit('slot-available');
  }

  getAvailableSlots() {
    return Math.max(0, this.maxConcurrent - this.currentCount);
  }
}

const rateLimiter = new RateLimiter(25, 2500);
const concurrencyLimiter = new ConcurrencyLimiter(75);

class UILogger extends EventEmitter {
  constructor(capacity = 500) {
    super();
    this.capacity = capacity;
    this.entries = [];
  }
  log(level, message, meta = {}) {
    const entry = {
      id: `${Date.now()}-${Math.random().toString(16).slice(2)}`,
      timestamp: new Date(),
      level,
      message,
      meta,
    };
    this.entries.push(entry);
    if (this.entries.length > this.capacity) this.entries.shift();
    this.emit('update', entry, this.entries);
  }
  info(message, meta) { this.log('info', message, meta); }
  warn(message, meta) { this.log('warn', message, meta); }
  error(message, meta) { this.log('error', message, meta); }
}

class TelemetryStore extends EventEmitter {
  constructor() {
    super();
    this.promptStats = new Map();
    this.referenceStats = new Map();
  }
  _ensurePrompt(name) {
    const key = name || '(unknown prompt)';
    if (!this.promptStats.has(key)) {
      this.promptStats.set(key, {
        name: key,
        success: 0,
        failure: 0,
        lastStatus: null,
        lastError: null,
        lastUpdate: null,
        errorCodes: {},
      });
    }
    return this.promptStats.get(key);
  }
  _ensureReference(name) {
    const key = name || '(unknown ref)';
    if (!this.referenceStats.has(key)) {
      this.referenceStats.set(key, {
        name: key,
        success: 0,
        failure: 0,
        lastStatus: null,
        lastError: null,
        lastUpdate: null,
        errorCodes: {},
      });
    }
    return this.referenceStats.get(key);
  }
  recordSuccess(promptName, references = []) {
    const promptRecord = this._ensurePrompt(promptName);
    promptRecord.success += 1;
    promptRecord.lastStatus = 'success';
    promptRecord.lastError = null;
    promptRecord.lastUpdate = new Date();
    references.forEach((refName) => {
      const refRecord = this._ensureReference(refName);
      refRecord.success += 1;
      refRecord.lastStatus = 'success';
      refRecord.lastError = null;
      refRecord.lastUpdate = new Date();
    });
    this.emit('update');
  }
  recordFailure(promptName, references = [], error) {
    const promptRecord = this._ensurePrompt(promptName);
    promptRecord.failure += 1;
    promptRecord.lastStatus = 'failure';
    promptRecord.lastError = error ? error.message || String(error) : null;
    promptRecord.lastUpdate = new Date();
    if (error && error.status) {
      promptRecord.errorCodes[error.status] = (promptRecord.errorCodes[error.status] || 0) + 1;
    }
    references.forEach((refName) => {
      const refRecord = this._ensureReference(refName);
      refRecord.failure += 1;
      refRecord.lastStatus = 'failure';
      refRecord.lastError = error ? error.message || String(error) : null;
      refRecord.lastUpdate = new Date();
      if (error && error.status) {
        refRecord.errorCodes[error.status] = (refRecord.errorCodes[error.status] || 0) + 1;
      }
    });
    this.emit('update');
  }
  _decorate(recordsMap) {
    return Array.from(recordsMap.values()).map((record) => {
      const total = record.success + record.failure;
      const failRate = total === 0 ? 0 : record.failure / total;
      return { ...record, total, failRate };
    });
  }
  getPromptStats() {
    return this._decorate(this.promptStats).sort(
      (a, b) => b.failRate - a.failRate || b.total - a.total
    );
  }
  getReferenceStats() {
    return this._decorate(this.referenceStats).sort(
      (a, b) => b.failRate - a.failRate || b.total - a.total
    );
  }
}

const formatBytes = (bytes) =>
  bytes < 1024 ? `${bytes} B` :
  bytes < 1024 * 1024 ? `${(bytes / 1024).toFixed(1)} KB` :
  `${(bytes / (1024 * 1024)).toFixed(2)} MB`;

const formatPercent = (value) => `${(Math.round((value || 0) * 1000) / 10).toFixed(1)}%`;

const formatDuration = (ms) => {
  if (!ms || ms < 1000) return `${ms || 0}ms`;
  const s = Math.floor(ms / 1000);
  const minutes = Math.floor(s / 60);
  const seconds = s % 60;
  return minutes === 0 ? `${seconds}s` : `${minutes}m ${seconds}s`;
};

const estimateBase64Size = (base64String) => base64String.length * 0.75;

async function compressImageBuffer(buffer, targetSizeBytes) {
  let quality = CONFIG.COMPRESSION_QUALITY;
  let compressed = buffer;
  let attempts = 0;
  const maxAttempts = 5;
  const metadata = await sharp(buffer).metadata();
  if (metadata.width > CONFIG.MAX_IMAGE_DIMENSION || metadata.height > CONFIG.MAX_IMAGE_DIMENSION) {
    compressed = await sharp(buffer)
      .resize(CONFIG.MAX_IMAGE_DIMENSION, CONFIG.MAX_IMAGE_DIMENSION, {
        fit: 'inside',
        withoutEnlargement: true,
      })
      .toBuffer();
  }
  while (attempts < maxAttempts) {
    const testBuffer = await sharp(compressed)
      .jpeg({ quality: Math.round(quality) })
      .toBuffer();
    const base64 = testBuffer.toString('base64');
    const estimatedSize = estimateBase64Size(base64);
    if (estimatedSize <= targetSizeBytes || quality <= 50) return base64;
    quality -= 10;
    attempts += 1;
    compressed = testBuffer;
  }
  const finalBuffer = await sharp(compressed).jpeg({ quality: 50 }).toBuffer();
  return finalBuffer.toString('base64');
}

async function ensureDirectories(logger = defaultLogger) {
  await fs.mkdir(CONFIG.PROMPTS_DIR, { recursive: true });
  await fs.mkdir(CONFIG.IMG2IMG_DIR, { recursive: true });
  await fs.mkdir(CONFIG.OUTPUT_DIR, { recursive: true });
  logger.info(
    `Directories ready:\n  • Prompts: ${CONFIG.PROMPTS_DIR}\n  • Img2Img: ${CONFIG.IMG2IMG_DIR}\n  • Output: ${CONFIG.OUTPUT_DIR}`
  );
}

async function loadPrompt(promptName) {
  const promptPath = path.join(CONFIG.PROMPTS_DIR, `${promptName}.txt`);
  try {
    return (await fs.readFile(promptPath, 'utf8')).trim();
  } catch {
    throw new Error(`Prompt file not found: ${promptPath}`);
  }
}

async function saveImg2Img(imgName, base64Data) {
  const imgPath = path.join(CONFIG.IMG2IMG_DIR, `${imgName}.json`);
  await fs.writeFile(imgPath, JSON.stringify({ base64: base64Data }, null, 2), 'utf8');
}

async function imageFileToBase64(filePath, compress = false) {
  const buffer = await fs.readFile(filePath);
  if (compress && CONFIG.AUTO_COMPRESS) {
    return compressImageBuffer(buffer, CONFIG.TARGET_IMAGE_SIZE);
  }
  return buffer.toString('base64');
}

async function loadImg2ImgOrConvert(imgName, logger = defaultLogger) {
  // Check if imgName is a media server reference (@ID)
  if (imgName.startsWith('@')) {
    const id = parseInt(imgName.substring(1), 10);
    if (Number.isNaN(id) || id < 1) {
      throw new Error(`Invalid media server ID: ${imgName}`);
    }
    return fetchMediaServerImage(id, logger);
  }
  // Check if imgName is an absolute path
  const isAbsolutePath = path.isAbsolute(imgName);
  const basePath = isAbsolutePath ? '' : CONFIG.IMG2IMG_DIR;

  const jsonPath = path.join(basePath, `${imgName}.json`);
  try {
    const data = await fs.readFile(jsonPath, 'utf8');
    const json = JSON.parse(data);
    return json.base64;
  } catch {
    const possibleExtensions = ['.png', '.jpg','.JPG', '.jpeg', '.webp'];
    for (const ext of possibleExtensions) {
      const imgPath = path.join(basePath, `${imgName}${ext}`);
      try {
        await fs.access(imgPath);
        // For absolute paths, don't save json to external locations
        if (isAbsolutePath) {
          logger.info(`Loading external image: ${imgName}${ext}`);
          const base64 = await imageFileToBase64(imgPath, true);
          return base64;
        }
        logger.info(`Auto-converting ${imgName}${ext} → ${imgName}.json`);
        const base64 = await imageFileToBase64(imgPath, true);
        await saveImg2Img(imgName, base64);
        return base64;
      } catch {
        /* continue */
      }
    }
    throw new Error(`img2img file not found: ${imgName} (tried .json, .png, .jpg, .jpeg, .webp)`);
  }
}

async function fetchMediaServerImage(id, logger = defaultLogger) {
  const url = `${CONFIG.MEDIA_SERVER_URL}/image/${id}/image`;
  logger.info(`Fetching media server image @${id}...`);
  // No proxy agent — media server is on the local network
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`Media server returned ${response.status} for image @${id}`);
  }
  const buffer = Buffer.from(await response.arrayBuffer());
  if (CONFIG.AUTO_COMPRESS) {
    return compressImageBuffer(buffer, CONFIG.TARGET_IMAGE_SIZE);
  }
  return buffer.toString('base64');
}

async function loadMultipleImg2Img(imgNames, { logger = defaultLogger } = {}) {
  const base64Array = [];
  const filenamesArray = [];
  let totalSize = 0;
  logger.info(`Loading ${imgNames.length} img2img reference(s)...`);
  const targetSizePerImage = CONFIG.AUTO_COMPRESS
    ? Math.floor(CONFIG.MAX_PAYLOAD_SIZE * 0.8 / Math.max(imgNames.length, 1))
    : CONFIG.TARGET_IMAGE_SIZE;
  for (let i = 0; i < imgNames.length; i += 1) {
    const imgName = imgNames[i];
    try {
      let base64 = await loadImg2ImgOrConvert(imgName, logger);
      let estimatedSize = estimateBase64Size(base64);
      if (CONFIG.AUTO_COMPRESS && estimatedSize > targetSizePerImage) {
        logger.warn(`Reference ${imgName} is large (${formatBytes(estimatedSize)}). Compressing...`);
        const buffer = Buffer.from(base64, 'base64');
        base64 = await compressImageBuffer(buffer, targetSizePerImage);
        estimatedSize = estimateBase64Size(base64);
        logger.info(`Compressed ${imgName} to ${formatBytes(estimatedSize)}`);
      } else {
        logger.info(`Loaded ${imgName} (${formatBytes(estimatedSize)})`);
      }
      if (totalSize + estimatedSize > CONFIG.MAX_PAYLOAD_SIZE) {
        logger.warn(`Payload limit reached. Skipping ${imgName} and remaining references.`);
        break;
      }
      base64Array.push(base64);
      filenamesArray.push(imgName);
      totalSize += estimatedSize;
    } catch (error) {
      logger.warn(`Failed to load ${imgName}: ${error.message}`);
    }
  }
  if (base64Array.length === 0) throw new Error('No valid img2img references loaded');
  if (base64Array.length > CONFIG.MAX_IMG2IMG_REFS) {
    logger.warn(`API supports max ${CONFIG.MAX_IMG2IMG_REFS} references. Truncating list.`);
    return {
      base64Array: base64Array.slice(0, CONFIG.MAX_IMG2IMG_REFS),
      filenamesArray: filenamesArray.slice(0, CONFIG.MAX_IMG2IMG_REFS),
    };
  }
  logger.info(`Img2img payload size: ${formatBytes(totalSize)} / ${formatBytes(CONFIG.MAX_PAYLOAD_SIZE)}`);
  return { base64Array, filenamesArray };
}

// Resolve directory path - handles $aliases and absolute vs relative paths
function resolveRefDirectory(dirName) {
  // First expand any $variables
  const expanded = expandPathAliases(dirName);

  // If it's an absolute path, use it directly
  if (path.isAbsolute(expanded)) {
    return { dirPath: expanded, isAbsolute: true, expanded };
  }

  // Otherwise, relative to IMG2IMG_DIR
  return { dirPath: path.join(CONFIG.IMG2IMG_DIR, expanded), isAbsolute: false, expanded };
}

async function getImagesFromDirectory(dirName, { logger = defaultLogger } = {}) {
  const { dirPath, isAbsolute, expanded } = resolveRefDirectory(dirName);
  try {
    const files = await fs.readdir(dirPath);
    const imageFiles = files.filter((f) =>
      ['.png', '.jpg', '.jpeg', '.webp', '.json'].includes(path.extname(f).toLowerCase())
    );
    if (imageFiles.length === 0) {
      logger.warn(`No images found in directory: ${dirName}`);
      return [];
    }
    // For absolute paths, return full path; for relative, return relative to IMG2IMG_DIR
    if (isAbsolute) {
      return imageFiles.map((f) => path.join(dirPath, path.parse(f).name));
    }
    return imageFiles.map((f) => path.join(expanded, path.parse(f).name));
  } catch (error) {
    logger.warn(`Could not read directory ${dirName}: ${error.message}`);
    return [];
  }
}

// Recursive version: get images from directory AND all subdirectories
async function getImagesFromDirectoryRecursive(dirName, { logger = defaultLogger } = {}) {
  const { dirPath, isAbsolute, expanded } = resolveRefDirectory(dirName);
  const allImages = [];

  async function scanDir(currentPath, relativeTo) {
    try {
      const files = await fs.readdir(currentPath, { withFileTypes: true });
      for (const file of files) {
        const fullFilePath = path.join(currentPath, file.name);
        if (file.isDirectory()) {
          await scanDir(fullFilePath, relativeTo);
        } else {
          const ext = path.extname(file.name).toLowerCase();
          if (['.png', '.jpg', '.JPG', '.jpeg', '.webp', '.json'].includes(ext)) {
            if (isAbsolute) {
              // For absolute paths, store full path without extension
              allImages.push(path.join(path.dirname(fullFilePath), path.parse(file.name).name));
            } else {
              // For relative paths, store relative to IMG2IMG_DIR
              const fileDirname = path.dirname(fullFilePath);
              const relativeDir = path.relative(CONFIG.IMG2IMG_DIR, fileDirname);
              const relDir = relativeDir === '.' ? '' : (relativeDir.replace(/\\/g, '/') + '/');
              allImages.push(relDir + path.parse(file.name).name);
            }
          }
        }
      }
    } catch (error) {
      logger.warn(`Error scanning ${currentPath}: ${error.message}`);
    }
  }

  await scanDir(dirPath, isAbsolute ? dirPath : CONFIG.IMG2IMG_DIR);
  return allImages;
}

async function getAllImagesRecursively({ logger = defaultLogger } = {}) {
  const allImages = [];
  async function scanDir(currentPath) {
    try {
      const files = await fs.readdir(currentPath, { withFileTypes: true });
      for (const file of files) {
        const fullFilePath = path.join(currentPath, file.name);
        if (file.isDirectory()) {
          await scanDir(fullFilePath);
        } else {
          const ext = path.extname(file.name).toLowerCase();
          if (['.png', '.jpg','.JPG', '.jpeg', '.webp', '.json'].includes(ext)) {
            const fileDirname = path.dirname(fullFilePath);
            const relativeDir = path.relative(CONFIG.IMG2IMG_DIR, fileDirname);
            const relDir = relativeDir === '.' ? '' : (relativeDir.replace(/\\/g, '/') + '/');
            const name = relDir + path.parse(file.name).name;
            if (!allImages.includes(name)) {
              allImages.push(name);
            }
          }
        }
      }
    } catch (error) {
      logger.warn(`Error scanning ${currentPath}: ${error.message}`);
    }
  }
  await scanDir(CONFIG.IMG2IMG_DIR);
  logger.info(`Found ${allImages.length} total images recursively in img2img.`);
  return allImages;
}

async function processImg2ImgWildcards(refsString, { logger = defaultLogger } = {}) {
  if (!refsString) return [];
  const refs = refsString.split(',').map((s) => s.trim()).filter(Boolean);
  const processed = [];
  for (const ref of refs) {
    // Check for @#N = pick N random images from media server
    const mediaNumMatch = ref.match(/^@#(\d+)$/);
    if (mediaNumMatch) {
      let num = parseInt(mediaNumMatch[1], 10);
      if (num > 10) {
        logger.warn(`@#${num} exceeds max 10, capping at 10`);
        num = 10;
      }
      if (num < 1) continue;
      const ids = new Set();
      while (ids.size < num) {
        ids.add(Math.floor(Math.random() * CONFIG.MEDIA_SERVER_MAX_ID) + 1);
      }
      logger.info(`Media server @#${num}: selected IDs ${[...ids].join(', ')}`);
      for (const id of ids) processed.push(`@${id}`);
      continue;
    }
    // Check for @? or @random = one random image from media server
    if (ref === '@?' || ref.toLowerCase() === '@random') {
      const id = Math.floor(Math.random() * CONFIG.MEDIA_SERVER_MAX_ID) + 1;
      logger.info(`Media server random: selected image @${id}`);
      processed.push(`@${id}`);
      continue;
    }
    // Check for @123 = specific media server image by ID
    const mediaIdMatch = ref.match(/^@(\d+)$/);
    if (mediaIdMatch) {
      processed.push(ref);
      continue;
    }
    // Check for !#N = pick N random images from all recursive img2img
    const numMatch = ref.match(/^!#(\d+)$/);
    if (numMatch) {
      let num = parseInt(numMatch[1], 10);
      if (num > 10) {
        logger.warn(`!#${num} exceeds max 10, capping at 10`);
        num = 10;
      }
      if (num < 1) continue;
      const allImages = await getAllImagesRecursively({ logger });
      if (allImages.length === 0) {
        logger.warn('No images found in img2img recursively for !# wildcard.');
        continue;
      }
      // Shuffle and pick unique random
      const shuffled = [...allImages].sort(() => 0.5 - Math.random());
      const selected = shuffled.slice(0, num);
      logger.info(`Wildcard !#${num}: selected ${num} random images from ${allImages.length} total`);
      processed.push(...selected);
      continue;
    }
    // Check for !!folder!! = use ALL images from folder (non-recursive)
    if (ref.startsWith('!!') && ref.endsWith('!!')) {
      const dirName = ref.substring(2, ref.length - 2);
      const images = await getImagesFromDirectory(dirName, { logger });
      if (images.length > 0) {
        logger.info(`Directory wildcard !!${dirName}!!: using all ${images.length} images`);
        processed.push(...images);
      } else {
        logger.warn(`Directory wildcard !!${dirName}!! has no images.`);
      }
      continue;
    }
    // Check for !!folder = use ONE random image from folder AND all subdirectories (recursive)
    if (ref.startsWith('!!') && !ref.endsWith('!!')) {
      const dirName = ref.substring(2);
      const images = await getImagesFromDirectoryRecursive(dirName, { logger });
      if (images.length > 0) {
        const selected = images[Math.floor(Math.random() * images.length)];
        logger.info(`Recursive wildcard !!${dirName}: selected ${path.basename(selected)} from ${images.length} total`);
        processed.push(selected);
      } else {
        logger.warn(`Recursive wildcard !!${dirName} has no images.`);
      }
      continue;
    }
    // Check for !folder = use ONE random image from folder (non-recursive)
    if (ref.startsWith('!')) {
      const dirName = ref.substring(1);
      const images = await getImagesFromDirectory(dirName, { logger });
      if (images.length > 0) {
        const selected = images[Math.floor(Math.random() * images.length)];
        logger.info(`Directory wildcard !${dirName}: selected ${path.basename(selected)}`);
        processed.push(selected);
      } else {
        logger.warn(`Directory wildcard !${dirName} has no images.`);
      }
      continue;
    }
    const wildcardMatch = ref.match(/^\{([^}]+)\}$/);
    if (wildcardMatch) {
      const options = wildcardMatch[1].split('|').map((s) => s.trim());
      const selected = options[Math.floor(Math.random() * options.length)];
      logger.info(`Wildcard ${ref} resolved to ${selected}`);
      processed.push(selected);
    } else {
      processed.push(ref);
    }
  }
  return processed;
}

function processPromptVariables(prompt, img2imgFilenames) {
  if (!img2imgFilenames || img2imgFilenames.length === 0) return prompt;
  prompt = prompt.replace(/%img2img\[(\d+)\]\.(filename|name|basename)%/g, (match, index, type) => {
    const idx = parseInt(index, 10);
    if (Number.isNaN(idx) || idx < 0 || idx >= img2imgFilenames.length) return match;
    const filename = img2imgFilenames[idx];
    const fullFilename = path.basename(filename);
    const nameWithoutExt = path.parse(fullFilename).name;
    if (type === 'filename') return fullFilename;
    if (type === 'name' || type === 'basename') return nameWithoutExt;
    return match;
  });
  const firstFilename = img2imgFilenames[0];
  const fullFilename = path.basename(firstFilename);
  const nameWithoutExt = path.parse(fullFilename).name;
  return prompt
    .replace(/%img2img\.filename%/g, fullFilename)
    .replace(/%img2img\.name%/g, nameWithoutExt)
    .replace(/%img2img\.basename%/g, nameWithoutExt);
}

function processWildcards(prompt) {
  const taggedChoices = new Map();
  const taggedWildcardRegex = /\{([^}]+)\}/g;
  const matches = [...prompt.matchAll(taggedWildcardRegex)];
  matches.forEach((match) => {
    const options = match[1].split('|').map((s) => s.trim());
    options.forEach((option) => {
      const tagMatch = option.match(/<([^>]+)>$/);
      if (tagMatch) {
        const tag = tagMatch[1];
        if (!taggedChoices.has(tag)) {
          taggedChoices.set(tag, option.replace(/<[^>]+>$/, '').trim());
        }
      }
    });
  });
  prompt = prompt.replace(taggedWildcardRegex, (match, options) => {
    const choices = options.split('|').map((s) => s.trim());
    for (const choice of choices) {
      const tagMatch = choice.match(/<([^>]+)>$/);
      if (tagMatch && taggedChoices.has(tagMatch[1])) {
        return choice.replace(/<[^>]+>$/, '').trim();
      }
    }
    const selected = choices[Math.floor(Math.random() * choices.length)];
    const tagMatch = selected.match(/<([^>]+)>$/);
    if (tagMatch) {
      const tag = tagMatch[1];
      const value = selected.replace(/<[^>]+>$/, '').trim();
      taggedChoices.set(tag, value);
      return value;
    }
    return selected;
  });
  const conditionalRegex = /<([^:>]+):([^>]+)>/g;
  prompt = prompt.replace(conditionalRegex, (match, tag, content) =>
    taggedChoices.has(tag) ? content.trim() : ''
  );
  return prompt.replace(/\s+/g, ' ').trim();
}

function addImg2ImgSafetyInstructions(prompt, hasImg2Img) {
  if (!hasImg2Img) return prompt;
  const safetyInstructions = `

[follow the user prompt exactly, do not deviate from the words stated. In the reference images, if there are any watermarks/logos always remove them / do not render them at all unless explicitly asked to do so. Never try and merge together faces and traits unless it is the same person stated by the following prompt or asked to do so explicitly, otherwise, always acknowledge that the reference images have multiple people with distinct key features that need to be retained in the generated image]
prompt:`;
  return prompt + safetyInstructions;
}

function parseQueueLine(line) {
  const trimmedLine = line.trim();

  // Check for disabled/skip prefix (?)
  const isDisabled = trimmedLine.startsWith('?');
  const lineWithoutDisableFlag = isDisabled ? trimmedLine.substring(1).trim() : trimmedLine;

  const hasRetryFlag = lineWithoutDisableFlag.endsWith('!');
  const cleanLine = lineWithoutDisableFlag.replace(/!$/, '').trim();
  const regex = /\[([^\]]+)\]/g;
  const matches = [...cleanLine.matchAll(regex)].map((m) => m[1].trim());
  if (matches.length < 1) return null;
  const config = {
    prompt: matches[0],
    width: CONFIG.DEFAULT_WIDTH,
    height: CONFIG.DEFAULT_HEIGHT,
    numImages: CONFIG.DEFAULT_IMAGES,
    numBatches: CONFIG.DEFAULT_BATCHES,
    model: CONFIG.DEFAULT_MODEL,
    img2imgRefsPattern: null,
    style: null,
    autoRetry: hasRetryFlag,
    disabled: isDisabled,
    // New model-specific parameters
    resolution: null,      // String resolution: "1k", "2k", "4k", "8k", "auto", or "1024x1024"
    aspect_ratio: null,    // Aspect ratio: "21:9", "16:9", "9:16", "5:4", "4:3", "3:4", "2:3", "3:2", "square", "auto"
    steps: null,           // For riverflow-2-max
    CFGScale: null,        // For riverflow-2-max
    strength: null,        // For riverflow-2-max
    seed: null,            // For wan-2.6-image-edit
  };

  // Parse model first (position 4) to determine how to handle resolution
  if (matches[4]) config.model = matches[4] || CONFIG.DEFAULT_MODEL;

  // Position 1: Resolution - can be WxH (e.g., "4096x4096") or string (e.g., "4k", "auto")
  if (matches[1]) {
    const resValue = matches[1].trim();
    const resParts = resValue.toLowerCase().split('x');

    // Check if it's a WxH format with numbers
    if (resParts.length === 2 && !isNaN(parseInt(resParts[0], 10)) && !isNaN(parseInt(resParts[1], 10))) {
      // Traditional WxH format (e.g., "4096x4096")
      config.width = parseInt(resParts[0], 10) || CONFIG.DEFAULT_WIDTH;
      config.height = parseInt(resParts[1], 10) || CONFIG.DEFAULT_HEIGHT;
    } else {
      // String resolution format (e.g., "4k", "auto", "1024x1024" for prunaai)
      config.resolution = resValue;
    }
  }

  if (matches[2]) config.numImages = parseInt(matches[2], 10) || CONFIG.DEFAULT_IMAGES;
  if (matches[3]) config.numBatches = parseInt(matches[3], 10) || CONFIG.DEFAULT_BATCHES;
  if (matches[5] && matches[5].toLowerCase() !== 'none') config.img2imgRefsPattern = matches[5];
  if (matches[6] && matches[6].toLowerCase() !== 'none') config.style = matches[6];

  // Position 7: Extended params as key=value pairs separated by commas
  // Example: [aspect_ratio=16:9,steps=30,CFGScale=7,strength=0.8,seed=16]
  if (matches[7]) {
    const extParams = matches[7].split(',').map(p => p.trim());
    extParams.forEach(param => {
      const [key, value] = param.split('=').map(s => s.trim());
      if (key && value) {
        switch (key.toLowerCase()) {
          case 'aspect_ratio':
          case 'aspectratio':
          case 'ar':
            config.aspect_ratio = value;
            break;
          case 'steps':
            config.steps = parseInt(value, 10);
            break;
          case 'cfgscale':
          case 'cfg':
            config.CFGScale = parseFloat(value);
            break;
          case 'strength':
            config.strength = parseFloat(value);
            break;
          case 'seed':
            config.seed = parseInt(value, 10);
            break;
          case 'resolution':
          case 'res':
            config.resolution = value;
            break;
        }
      }
    });
  }

  return config;
}

async function parseQueueFile(logger = defaultLogger) {
  try {
    const content = await fs.readFile(CONFIG.QUEUE_FILE, 'utf8');
    const lines = content.split('\n').map((l) => l.trim()).filter((l) => l && !l.startsWith('#'));
    const jobs = [];
    let disabledCount = 0;
    lines.forEach((line, idx) => {
      try {
        const job = parseQueueLine(line);
        if (job && job.prompt) {
          if (job.disabled) {
            disabledCount++;
            logger.info(`Skipping disabled queue line ${idx + 1}: ?[${job.prompt}]...`);
          } else {
            jobs.push(job);
          }
        } else {
          logger.warn(`Skipping invalid queue line ${idx + 1}: ${line.substring(0, 50)}...`);
        }
      } catch (err) {
        logger.error(`Error parsing queue line ${idx + 1}: ${err.message}`);
      }
    });
    if (disabledCount > 0) {
      logger.info(`Found ${disabledCount} disabled queue entr${disabledCount === 1 ? 'y' : 'ies'} (marked with ?)`);
    }
    return jobs;
  } catch (error) {
    logger.error(`Failed to read queue file: ${CONFIG.QUEUE_FILE}`);
    throw error;
  }
}

async function saveImage(base64Data, filename) {
  const filepath = path.join(CONFIG.OUTPUT_DIR, filename);
  const imageBuffer = Buffer.from(base64Data, 'base64');
  await fs.writeFile(filepath, imageBuffer);
  const stats = await fs.stat(filepath);
  return { filepath, size: stats.size };
}

async function logImageResult(success, promptName, references, metadata = {}) {
  try {
    const timestamp = new Date().toISOString();
    const status = success ? 'SUCCESS' : 'FAILURE';
    const promptText = metadata.promptText || promptName;
    const model = metadata.model || CONFIG.DEFAULT_MODEL;
    const width = metadata.width || CONFIG.DEFAULT_WIDTH;
    const height = metadata.height || CONFIG.DEFAULT_HEIGHT;
    const filename = metadata.filename || '';
    const errorMsg = metadata.error || '';

    // Write to CSV (backup/quick view)
    const refColumns = references && references.length > 0
      ? references.map(ref => `"${ref}"`).join(',')
      : '';
    const csvLine = `${timestamp},${status},"${promptName}",${model},${width},${height},${filename},${refColumns},"${errorMsg.replace(/"/g, '""')}"\n`;

    let needsHeader = false;
    try {
      await fs.access(CONFIG.IMAGE_RESULTS_LOG);
    } catch {
      needsHeader = true;
    }

    if (needsHeader) {
      const header = 'timestamp,status,prompt_name,model,width,height,filename,references,error\n';
      await fs.writeFile(CONFIG.IMAGE_RESULTS_LOG, header, 'utf8');
    }

    await fs.appendFile(CONFIG.IMAGE_RESULTS_LOG, csvLine, 'utf8');

    // Write to SQLite with embeddings
    const database = initDatabase();
    const embedding = await generateEmbedding(promptText);
    const refsJson = JSON.stringify(references || []);

    const insertStmt = database.prepare(`
      INSERT INTO image_results
        (timestamp, status, prompt_name, prompt_text, prompt_embedding, refs, model, width, height, filename, error)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `);

    insertStmt.run(
      timestamp,
      status,
      promptName,
      promptText,
      embedding,
      refsJson,
      model,
      width,
      height,
      filename,
      errorMsg
    );

  } catch (error) {
    console.error('Failed to write image result log:', error.message);
  }
}

async function logQueueJobCompletion(job) {
  if (!job.metadata.queue) return;

  const queueIndex = job.metadata.queueIndex || 0;
  const promptName = job.promptName || 'unknown';
  const status = job.state === 'completed' ? 'DONE' : job.state === 'failed' ? 'FAILED' : job.state.toUpperCase();

  const numImages = job.options.numImages || 0;
  const numBatches = job.options.numBatches || 0;
  const expectedTotal = numImages * numBatches;
  const actualImages = job.stats.totalImages || 0;
  const percent = expectedTotal > 0 ? Math.round((actualImages / expectedTotal) * 100) : 0;
  const progress = `${actualImages}/${expectedTotal} (${percent}%)`;

  const model = job.options.model || CONFIG.DEFAULT_MODEL;
  const refs = job.img2imgRefsPattern || 'none';

  const timestamp = new Date().toISOString();
  const errorInfo = job.lastError ? ` | Error: ${job.lastError.message}` : '';

  const logLine = `[${timestamp}] Job #${queueIndex} | Prompt: ${promptName} | Status: ${status} | Progress: ${progress} | Model: ${model} | Refs: ${refs}${errorInfo}\n`;

  try {
    await fs.appendFile(CONFIG.QUEUE_LOG_FILE, logLine, 'utf8');
  } catch (error) {
    console.error('Failed to write to queue log:', error.message);
  }
}

async function generateBatch(rawPrompt, options, batchIndex, context = {}) {
  const logger = context.logger || defaultLogger;
  const hasImg2Img = options.img2imgBase64Array && options.img2imgBase64Array.length > 0;
  let processedPrompt = processPromptVariables(rawPrompt, options.img2imgFilenames);
  processedPrompt = processWildcards(processedPrompt);
  processedPrompt = addImg2ImgSafetyInstructions(processedPrompt, hasImg2Img);
  const width = options.width || CONFIG.DEFAULT_WIDTH;
  const height = options.height || CONFIG.DEFAULT_HEIGHT;
  const numImages = options.numImages || CONFIG.DEFAULT_IMAGES;
  const model = options.model || CONFIG.DEFAULT_MODEL;

  // Build request body based on model type
  const requestBody = {
    prompt: processedPrompt,
    model: model,
    nImages: numImages,
    responseFormat: 'b64_json',
    showExplicitContent: true,
  };

  // Handle resolution-based models (nano-banana, riverflow, wan, prunaai)
  if (isResolutionBasedModel(model) || options.resolution) {
    // Use string resolution if provided, otherwise default to 'auto'
    requestBody.resolution = options.resolution || 'auto';

    // Add aspect_ratio for models that support it
    if (options.aspect_ratio) {
      requestBody.aspect_ratio = options.aspect_ratio;
    } else if (model.includes('nano-banana')) {
      // Default aspect_ratio for nano-banana models
      requestBody.aspect_ratio = 'auto';
    }
  } else {
    // Traditional width/height based models
    requestBody.width = width;
    requestBody.height = height;
    requestBody.resolution = `${width}x${height}`;
  }

  // Add img2img references
  if (options.img2imgBase64Array && options.img2imgBase64Array.length > 0) {
    requestBody.imageDataUrls = options.img2imgBase64Array.map(
      (base64) => `data:image/png;base64,${base64}`
    );
  }

  if (options.style) requestBody.style = options.style;

  // Model-specific parameters
  if (model === 'seedream-v3') {
    if (options.guidanceScale !== undefined) requestBody.guidance_scale = options.guidanceScale;
    if (options.safetyChecker !== undefined) requestBody.enable_safety_checker = options.safetyChecker;
  }

  // riverflow-2-max specific parameters
  if (model.includes('riverflow')) {
    if (options.steps !== undefined) requestBody.steps = options.steps;
    if (options.CFGScale !== undefined) requestBody.CFGScale = options.CFGScale;
    if (options.strength !== undefined) requestBody.strength = options.strength;
  }

  // wan-2.6-image-edit specific parameters
  if (model.includes('wan-')) {
    if (options.seed !== undefined) requestBody.seed = options.seed;
  }

  // prunaai models use resolution string format like "1024x1024"
  // (already handled above with options.resolution)
  const payloadString = JSON.stringify(requestBody);
  const payloadSize = Buffer.byteLength(payloadString, 'utf8');
  logger.info(`Batch ${batchIndex}: Sending request (${formatBytes(payloadSize)})`);
  const startedAt = Date.now();
  const response = await fetch(CONFIG.API_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'x-api-key': CONFIG.API_KEY },
    body: payloadString,
    agent: proxyAgent, // Route through SOCKS proxy
  });
  if (!response.ok) {
    const errorText = await response.text();
    const error = new Error(`API request failed (${response.status}): ${errorText.slice(0, 200)}`);
    error.status = response.status;
    error.details = errorText;
    if (response.status === 413 || errorText.toLowerCase().includes('payload')) {
      error.hint = 'Payload too large. Reduce number of references or enable compression.';
    }
    throw error;
  }
  const data = await response.json();
  if (!data || !Array.isArray(data.data)) {
    const error = new Error('API response missing data array');
    error.status = response.status;
    throw error;
  }
  const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
  const promptPart = processedPrompt.substring(0, 30).replace(/[^a-z0-9]/gi, '_').toLowerCase();
  const savedFiles = [];
  for (let i = 0; i < data.data.length; i += 1) {
    const imageItem = data.data[i];
    const base64Data = imageItem.b64_json || imageItem.image || imageItem;
    if (typeof base64Data === 'string') {
      const uniqueId = `${timestamp}_batch${batchIndex}_img${i}`;
      const filename = `generated_${uniqueId}_${promptPart}.png`;
      const saved = await saveImage(base64Data, filename);
      savedFiles.push({ filename, size: saved.size, path: saved.filepath });
    }
  }
  const elapsedMs = Date.now() - startedAt;
  logger.info(`Batch ${batchIndex}: Success (${savedFiles.length} image(s) in ${formatDuration(elapsedMs)})`);
  return {
    imageCount: savedFiles.length,
    savedFiles,
    referencesUsed: options.img2imgFilenames || [],
    promptUsed: processedPrompt,
    elapsedMs,
  };
}

class JobManager extends EventEmitter {
  constructor(telemetry, logger = defaultLogger) {
    super();
    this.telemetry = telemetry;
    this.logger = logger;
    this.jobs = new Map();
    this.jobOrder = [];
    this.sequence = 0;
    this.pendingQueue = [];
    this.currentJobs = new Set();
    this.maxConcurrentJobs = CONFIG.MAX_CONCURRENT_JOBS;
    this.globalStats = {
      startedAt: Date.now(),
      totalJobs: 0,
      completedJobs: 0,
      failedJobs: 0,
      runningJobs: 0,
      totalBatches: 0,
      successfulBatches: 0,
      failedBatches: 0,
      totalImages: 0,
    };
    this.queuePlan = null;
    this.queueActiveJobIds = new Set();
    this.queueRunState = {
      running: false,
      startedAt: null,
      finishedAt: null,
      totalJobs: 0,
    };

    // Global request queue and dispatcher
    this.requestQueue = [];
    this.inFlightRequests = new Map(); // Track live API calls
    this.dispatcherRunning = false;
    this.rateLimiter = rateLimiter;
    this.concurrencyLimiter = concurrencyLimiter;
    this.cancelRequested = false;
    this.cancelPromise = null;
    this.cancelResolve = null;

    // Listen for slot availability
    this.concurrencyLimiter.on('slot-available', () => {
      this._dispatchRequests();
    });
  }
  createJob(config) {
    const id = `job-${++this.sequence}`;
    const job = {
      id,
      source: config.source || 'interactive',
      promptName: config.promptName || 'custom',
      promptText: config.promptText,
      options: config.options || {},
      img2imgRefsPattern: config.img2imgRefsPattern || null,
      autoRetry: Boolean(config.autoRetry),
      targetImages: config.targetImages || null,
      tolerance: config.tolerance ?? CONFIG.AUTO_RETRY_TOLERANCE,
      metadata: config.metadata || {},
      createdAt: Date.now(),
      state: 'queued',
      startedAt: null,
      finishedAt: null,
      lastError: null,
      cachedRefs: null,
      stats: {
        totalBatches: 0,
        successfulBatches: 0,
        failedBatches: 0,
        totalImages: 0,
        batchHistory: [],
        lastBatch: null,
        errorCodes: {},
      },
    };
    return job;
  }
  enqueueJob(job) {
    if (!job || !job.id) throw new Error('Invalid job');
    this.jobs.set(job.id, job);
    this.jobOrder.push(job.id);
    this.globalStats.totalJobs += 1;
    this.pendingQueue.push(job);
    this.emit('job:queued', job);
    this.emit('stats:update', this.globalStats);
    this._tick();
    return job;
  }
  async startQueue() {
    if (this.queueRunState.running || (this.queueActiveJobIds && this.queueActiveJobIds.size > 0)) {
      this.logger.warn('Queue processing is already in progress.');
      return;
    }
    let queueJobs;
    try {
      queueJobs = await parseQueueFile(this.logger);
    } catch (error) {
      this.logger.error(`Unable to load queue file: ${error.message}`);
      return;
    }
    if (!queueJobs || queueJobs.length === 0) {
      this.logger.warn('Queue file contains no jobs.');
      return;
    }
    this.queuePlan = queueJobs.map((job, index) => ({
      index: index + 1,
      prompt: job.prompt,
      status: 'pending',
      jobId: null,
      config: job,
      result: null,
    }));
    this.queueRunState = {
      running: true,
      startedAt: Date.now(),
      finishedAt: null,
      totalJobs: queueJobs.length,
    };
    this.queueActiveJobIds = new Set();
    this.emit('queue:start', this.queuePlan);
    this.emit('queue:update', this.queuePlan);
    for (let i = 0; i < queueJobs.length; i += 1) {
      const queueJob = queueJobs[i];
      try {
        // Handle wildcard prompt syntax: {prompt1|prompt2|prompt3}
        let initialPromptName = queueJob.prompt;
        const wildcardMatch = queueJob.prompt.match(/^\{([^}]+)\}$/);
        if (wildcardMatch) {
          const options = wildcardMatch[1].split('|').map(s => s.trim());
          initialPromptName = options[0]; // Use first option for initial load
          this.logger.info(`Wildcard prompt detected: ${options.length} options, using "${initialPromptName}" for initial load`);
        }
        const promptText = await loadPrompt(initialPromptName);
        const job = this.createJob({
          source: 'queue',
          promptName: queueJob.prompt, // Store original (possibly wildcard) pattern
          promptText,
          options: {
            width: queueJob.width,
            height: queueJob.height,
            numImages: queueJob.numImages,
            numBatches: queueJob.numBatches,
            model: queueJob.model,
            style: queueJob.style,
            // New model-specific parameters
            resolution: queueJob.resolution,
            aspect_ratio: queueJob.aspect_ratio,
            steps: queueJob.steps,
            CFGScale: queueJob.CFGScale,
            strength: queueJob.strength,
            seed: queueJob.seed,
          },
          img2imgRefsPattern: queueJob.img2imgRefsPattern,
          autoRetry: queueJob.autoRetry,
          targetImages: queueJob.autoRetry ? queueJob.numImages * queueJob.numBatches : null,
          tolerance: queueJob.tolerance ?? CONFIG.AUTO_RETRY_TOLERANCE,
          metadata: {
            queue: true,
            queueIndex: i + 1,
            queueTotal: queueJobs.length,
          },
        });
        const planEntry = this.queuePlan[i];
        planEntry.jobId = job.id;
        job.metadata.queuePlanEntry = planEntry;
        this.queueActiveJobIds.add(job.id);
        this.enqueueJob(job);
      } catch (error) {
        this.logger.error(`Failed to prepare queue job "${queueJob.prompt}": ${error.message}`);
        const planEntry = this.queuePlan[i];
        planEntry.status = 'failed';
        planEntry.result = { success: false, error };
        this.emit('queue:update', this.queuePlan);
      }
    }
  }
  getJobs() {
    return this.jobOrder.map((id) => this.jobs.get(id));
  }

  async cancelAllRequests() {
    if (this.cancelRequested) {
      this.logger.warn('Cancellation already in progress...');
      return this.cancelPromise;
    }

    const queuedCount = this.requestQueue.length;
    const liveCount = this.inFlightRequests.size;

    this.logger.warn(`Cancellation requested: ${queuedCount} queued, ${liveCount} live requests`);
    this.cancelRequested = true;

    // Cancel all queued requests immediately
    const queuedRequests = [...this.requestQueue];
    this.requestQueue = [];
    queuedRequests.forEach(req => {
      req.cancelled = true;
      req.reject(new Error('Request cancelled'));
    });

    this.logger.info(`Cancelled ${queuedCount} queued request(s)`);

    // If there are live requests, wait for them
    if (liveCount > 0) {
      this.logger.warn(`Waiting for ${liveCount} live request(s) to complete...`);
      this.cancelPromise = new Promise((resolve) => {
        this.cancelResolve = resolve;
      });

      // Also set a timeout handler to check progress
      const checkInterval = setInterval(() => {
        const remaining = this.inFlightRequests.size;
        if (remaining > 0) {
          this.logger.info(`Still waiting for ${remaining} live request(s)...`);
        } else {
          clearInterval(checkInterval);
        }
      }, 3000);

      await this.cancelPromise;
      clearInterval(checkInterval);
      this.logger.info('All live requests completed. Cancellation finished.');
    } else {
      this.logger.info('No live requests. Cancellation complete.');
    }

    this.cancelRequested = false;
    this.cancelPromise = null;
  }

  resumeAfterCancel() {
    if (!this.cancelRequested) return;
    this.logger.info('Resuming request processing...');
    this.cancelRequested = false;
    this._dispatchRequests();
  }

  getRequestStats() {
    return {
      queued: this.requestQueue.length,
      live: this.inFlightRequests.size,
      total: this.requestQueue.length + this.inFlightRequests.size,
    };
  }

  _queueRequest(job, batchOptions, batchIndex, totalBatches, references, mode) {
    return new Promise((resolve, reject) => {
      const requestId = `${job.id}-batch-${batchIndex}`;
      const request = {
        id: requestId,
        job,
        batchOptions,
        batchIndex,
        totalBatches,
        references,
        mode,
        resolve,
        reject,
        createdAt: Date.now(),
        cancelled: false,
      };
      this.requestQueue.push(request);
      this._dispatchRequests();
    });
  }

  async _dispatchRequests() {
    if (this.dispatcherRunning) return;
    this.dispatcherRunning = true;

    try {
      while (this.requestQueue.length > 0 && !this.cancelRequested) {
        // Check if we can dispatch more requests
        if (!this.concurrencyLimiter.canStart()) {
          break;
        }

        if (!this.rateLimiter.canMakeCall()) {
          const waitTime = this.rateLimiter.getNextAvailableTime();
          if (waitTime > 0) {
            setTimeout(() => this._dispatchRequests(), waitTime);
            break;
          }
        }

        // Dequeue and dispatch
        const request = this.requestQueue.shift();

        // Skip if request was cancelled while in queue
        if (request.cancelled) {
          request.reject(new Error('Request cancelled'));
          continue;
        }

        this.rateLimiter.recordCall();
        this.concurrencyLimiter.increment();
        this.inFlightRequests.set(request.id, request);
        this.emit('stats:update', this.globalStats);

        // Execute the request asynchronously
        this._executeRequest(request).finally(() => {
          this.inFlightRequests.delete(request.id);
          this.concurrencyLimiter.decrement();
          this.emit('stats:update', this.globalStats);

          // Check if cancellation is complete
          if (this.cancelRequested && this.inFlightRequests.size === 0 && this.requestQueue.length === 0) {
            if (this.cancelResolve) {
              this.cancelResolve();
              this.cancelResolve = null;
            }
          }
        });
      }
    } finally {
      this.dispatcherRunning = false;
    }
  }

  async _executeRequest(request) {
    const { job, batchOptions, batchIndex, references, resolve, reject } = request;

    this.emit('batch:start', {
      jobId: job.id,
      batchIndex,
      totalBatches: request.totalBatches,
      references,
      mode: request.mode,
    });

    // Reload prompt from file each batch (allows real-time editing)
    // Also supports wildcard syntax: {prompt1|prompt2|prompt3} picks random each batch
    let currentPromptText = job.promptText;
    let currentPromptName = job.promptName;
    if (job.promptName) {
      try {
        // Check for wildcard syntax in prompt name: {option1|option2|option3}
        const wildcardMatch = job.promptName.match(/^\{([^}]+)\}$/);
        if (wildcardMatch) {
          const options = wildcardMatch[1].split('|').map(s => s.trim());
          currentPromptName = options[Math.floor(Math.random() * options.length)];
          this.logger.info(`Prompt wildcard: selected "${currentPromptName}" from ${options.length} options`);
        }
        currentPromptText = await loadPrompt(currentPromptName);
      } catch (err) {
        this.logger.warn(`Failed to reload prompt ${currentPromptName}, using cached: ${err.message}`);
      }
    }

    try {
      const result = await generateBatch(
        currentPromptText,
        batchOptions,
        batchIndex,
        { logger: this.logger, promptName: currentPromptName }
      );

      // Log each individual image success
      if (result.savedFiles && result.savedFiles.length > 0) {
        for (const savedFile of result.savedFiles) {
          await logImageResult(true, currentPromptName, references, {
            promptText: currentPromptText,
            model: batchOptions.model,
            width: batchOptions.width,
            height: batchOptions.height,
            filename: savedFile.filename,
          });
        }
      }

      this._handleBatchSuccess(job, result, batchIndex);
      resolve(result);
    } catch (error) {
      this.logger.error(`[${job.id}] Batch ${batchIndex} failed: ${error.message}`);

      // Log failure for expected number of images
      const expectedImages = batchOptions.numImages || CONFIG.DEFAULT_IMAGES;
      for (let i = 0; i < expectedImages; i++) {
        await logImageResult(false, currentPromptName, references, {
          promptText: currentPromptText,
          model: batchOptions.model,
          width: batchOptions.width,
          height: batchOptions.height,
          error: error.message || String(error),
        });
      }

      this._handleBatchFailure(job, error, batchIndex, references);
      job.lastError = error;
      reject(error);
    }
  }
  async _tick() {
    // Start ALL jobs immediately - they'll queue their batches into the global pipeline
    // No job-level concurrency limiting - only batch-level (75 live requests)
    while (this.pendingQueue.length > 0) {
      const nextJob = this.pendingQueue.shift();
      this.currentJobs.add(nextJob.id);

      // Run job asynchronously without awaiting - it will queue all its batches immediately
      this._runJob(nextJob).finally(() => {
        this.currentJobs.delete(nextJob.id);

        // Check if we're completely done
        if (this.pendingQueue.length === 0 && this.currentJobs.size === 0) {
          this.emit('idle');
          if (this.queueRunState.running && this.queueActiveJobIds.size === 0) {
            this.queueRunState.running = false;
            this.queueRunState.finishedAt = Date.now();
            this.emit('queue:complete', {
              plan: this.queuePlan,
              startedAt: this.queueRunState.startedAt,
              finishedAt: this.queueRunState.finishedAt,
            });
          }
        }
      });
    }
  }
  async _runJob(job) {
    job.state = 'running';
    job.startedAt = Date.now();
    this.globalStats.runningJobs += 1;
    this.emit('stats:update', this.globalStats);
    if (job.metadata.queuePlanEntry) {
      job.metadata.queuePlanEntry.status = 'running';
      this.emit('queue:update', this.queuePlan);
    }
    this.emit('job:start', job);
    this.logger.info(`[${job.id}] Started (${job.promptName})`);
    try {
      if (job.autoRetry) await this._runAutoRetry(job);
      else await this._runFixed(job);
      job.state = 'completed';
      this.globalStats.completedJobs += 1;
      if (job.metadata.queuePlanEntry) {
        job.metadata.queuePlanEntry.status = 'completed';
        job.metadata.queuePlanEntry.result = { success: true, stats: job.stats };
        this.emit('queue:update', this.queuePlan);
      }
      this.logger.info(`[${job.id}] Completed (${job.stats.totalImages} image(s))`);
    } catch (error) {
      job.state = 'failed';
      job.lastError = error;
      this.globalStats.failedJobs += 1;
      if (job.metadata.queuePlanEntry) {
        job.metadata.queuePlanEntry.status = 'failed';
        job.metadata.queuePlanEntry.result = { success: false, error };
        this.emit('queue:update', this.queuePlan);
      }
      this.logger.error(`[${job.id}] Failed: ${error.message}`);
    } finally {
      job.finishedAt = Date.now();
      this.globalStats.runningJobs = Math.max(this.globalStats.runningJobs - 1, 0);
      this.emit('stats:update', this.globalStats);
      this.emit('job:complete', job);

      // Log queue job completion to file
      await logQueueJobCompletion(job);

      if (job.metadata.queue) {
        this.queueActiveJobIds.delete(job.id);
        if (this.queueRunState.running && this.queueActiveJobIds.size === 0) {
          this.queueRunState.running = false;
          this.queueRunState.finishedAt = Date.now();
          this.emit('queue:complete', {
            plan: this.queuePlan,
            startedAt: this.queueRunState.startedAt,
            finishedAt: this.queueRunState.finishedAt,
          });
        }
      }
    }
  }
  async _prepareBatchOptions(job) {
    const baseOptions = {
      width: job.options.width || CONFIG.DEFAULT_WIDTH,
      height: job.options.height || CONFIG.DEFAULT_HEIGHT,
      numImages: job.options.numImages || CONFIG.DEFAULT_IMAGES,
      model: job.options.model || CONFIG.DEFAULT_MODEL,
      style: job.options.style || null,
      guidanceScale: job.options.guidanceScale,
      safetyChecker: job.options.safetyChecker,
      // New model-specific parameters
      resolution: job.options.resolution,
      aspect_ratio: job.options.aspect_ratio,
      steps: job.options.steps,
      CFGScale: job.options.CFGScale,
      strength: job.options.strength,
      seed: job.options.seed,
    };
    let img2imgBase64Array = [];
    let img2imgFilenames = [];
    if (job.img2imgRefsPattern) {
      const pattern = job.img2imgRefsPattern;
      const cached = job.cachedRefs;
      const hasWildcard = /[{}!@]/.test(pattern);
      if (cached && cached.pattern === pattern && !cached.hasWildcard) {
        img2imgBase64Array = [...cached.base64Array];
        img2imgFilenames = [...cached.filenamesArray];
      } else {
        const resolvedRefs = await processImg2ImgWildcards(pattern, { logger: this.logger });
        if (resolvedRefs.length > 0) {
          const loaded = await loadMultipleImg2Img(resolvedRefs, { logger: this.logger });
          img2imgBase64Array = loaded.base64Array;
          img2imgFilenames = loaded.filenamesArray;
          if (!hasWildcard) {
            job.cachedRefs = {
              pattern,
              hasWildcard,
              base64Array: [...img2imgBase64Array],
              filenamesArray: [...img2imgFilenames],
            };
          }
        }
      }
    } else {
      if (job.options.img2imgBase64Array && job.options.img2imgBase64Array.length > 0) {
        img2imgBase64Array = [...job.options.img2imgBase64Array];
      }
      if (job.options.img2imgFilenames && job.options.img2imgFilenames.length > 0) {
        img2imgFilenames = [...job.options.img2imgFilenames];
      }
    }
    return { ...baseOptions, img2imgBase64Array, img2imgFilenames };
  }
  _handleBatchSuccess(job, result, batchIndex) {
    job.stats.totalBatches += 1;
    job.stats.successfulBatches += 1;
    job.stats.totalImages += result.imageCount;
    job.stats.lastBatch = {
      status: 'success',
      batchIndex,
      imageCount: result.imageCount,
      elapsedMs: result.elapsedMs,
      references: result.referencesUsed || [],
      savedFiles: result.savedFiles,
      promptUsed: result.promptUsed,
    };
    job.stats.batchHistory.push({
      type: 'success',
      timestamp: Date.now(),
      ...job.stats.lastBatch,
    });
    this.globalStats.totalBatches += 1;
    this.globalStats.successfulBatches += 1;
    this.globalStats.totalImages += result.imageCount;
    this.telemetry.recordSuccess(job.promptName, result.referencesUsed || []);
    this.emit('batch:success', { jobId: job.id, batchIndex, result });
    this.emit('stats:update', this.globalStats);
  }
  _handleBatchFailure(job, error, batchIndex, referencesUsed = []) {
    job.stats.totalBatches += 1;
    job.stats.failedBatches += 1;
    job.stats.lastError = error;
    if (error && error.status) {
      job.stats.errorCodes[error.status] = (job.stats.errorCodes[error.status] || 0) + 1;
    }
    job.stats.lastBatch = {
      status: 'failure',
      batchIndex,
      error,
      references: referencesUsed,
    };
    job.stats.batchHistory.push({
      type: 'failure',
      timestamp: Date.now(),
      batchIndex,
      error,
      references: referencesUsed,
    });
    this.globalStats.totalBatches += 1;
    this.globalStats.failedBatches += 1;
    this.telemetry.recordFailure(job.promptName, referencesUsed, error);
    this.emit('batch:failure', { jobId: job.id, batchIndex, error, references: referencesUsed });
    this.emit('stats:update', this.globalStats);
  }
  async _runFixed(job) {
    const totalBatches = job.options.numBatches || CONFIG.DEFAULT_BATCHES;
    const batchPromises = [];

    // Queue all batches immediately - they'll flow through the global request queue
    for (let i = 0; i < totalBatches; i += 1) {
      const batchIndex = i + 1;

      // Prepare options once per batch
      const batchOptions = await this._prepareBatchOptions(job);
      const referencesUsed = batchOptions.img2imgFilenames || [];

      // Queue the request (non-blocking) - it goes into the global queue immediately
      const promise = this._queueRequest(
        job,
        batchOptions,
        batchIndex,
        totalBatches,
        referencesUsed,
        'fixed'
      ).catch(error => {
        // Error already handled in _executeRequest
        return null;
      });

      batchPromises.push(promise);
    }

    // Wait for all batches to complete
    await Promise.all(batchPromises);
  }
  async _runAutoRetry(job) {
    const imagesPerBatch = job.options.numImages || CONFIG.DEFAULT_IMAGES;
    const targetImages = job.targetImages || imagesPerBatch * (job.options.numBatches || CONFIG.DEFAULT_BATCHES);
    const tolerance = job.tolerance ?? CONFIG.AUTO_RETRY_TOLERANCE;

    while (job.stats.totalImages < targetImages - tolerance) {
      const remaining = targetImages - job.stats.totalImages;
      const batchesToRun = Math.ceil(remaining / imagesPerBatch);
      const batchPromises = [];

      // Queue all needed batches immediately - they go into global queue
      for (let i = 0; i < batchesToRun; i += 1) {
        const batchIndex = job.stats.totalBatches + i + 1;
        const batchOptions = await this._prepareBatchOptions(job);
        const referencesUsed = batchOptions.img2imgFilenames || [];

        // Queue the request (non-blocking) - flows through global pipeline
        const promise = this._queueRequest(
          job,
          batchOptions,
          batchIndex,
          null, // no fixed total for auto-retry
          referencesUsed,
          'auto'
        ).catch(error => {
          // Error already handled in _executeRequest
          return null;
        });

        batchPromises.push(promise);
      }

      // Wait for all batches in this round to complete
      await Promise.all(batchPromises);

      if (
        job.stats.totalImages >= targetImages - tolerance &&
        job.stats.totalImages <= targetImages + tolerance
      ) {
        this.logger.info(`[${job.id}] Target reached (${job.stats.totalImages}/${targetImages} images)`);
        return;
      }

      if (job.stats.totalBatches > 20000) throw new Error('Safety limit reached (20000 batches)');
    }
  }
  pauseJob(jobId) {
    const job = this.jobs.get(jobId);
    if (!job) return false;
    if (job.state === 'running' || job.state === 'queued') {
      job.state = 'paused';
      this.emit('job:paused', job);
      return true;
    }
    return false;
  }
  resumeJob(jobId) {
    const job = this.jobs.get(jobId);
    if (!job) return false;
    if (job.state === 'paused') {
      job.state = 'queued';
      this.pendingQueue.push(job);
      this._tick();
      this.emit('job:resumed', job);
      return true;
    }
    return false;
  }
  cancelJob(jobId) {
    const job = this.jobs.get(jobId);
    if (!job) return false;
    job.state = 'cancelled';
    this.emit('job:cancelled', job);
    return true;
  }
  removeJob(jobId) {
    const job = this.jobs.get(jobId);
    if (!job) return false;
    this.jobs.delete(jobId);
    const idx = this.jobOrder.indexOf(jobId);
    if (idx > -1) this.jobOrder.splice(idx, 1);
    this.emit('job:removed', job);
    return true;
  }
}

async function listPrompts() {
  try {
    const files = await fs.readdir(CONFIG.PROMPTS_DIR);
    return files.filter((f) => f.endsWith('.txt')).map((f) => f.replace('.txt', ''));
  } catch {
    return [];
  }
}

async function listImg2ImgRefs() {
  try {
    const files = await fs.readdir(CONFIG.IMG2IMG_DIR);
    return files.filter((f) => f.endsWith('.json')).map((f) => f.replace('.json', ''));
  } catch {
    return [];
  }
}

async function refreshAssets(state, logger) {
  const [prompts, references, queueData] = await Promise.all([
    listPrompts(),
    listImg2ImgRefs(),
    (async () => {
      try {
        const content = await fs.readFile(CONFIG.QUEUE_FILE, 'utf8');
        const lines = content.split('\n').map((l) => l.trim()).filter((l) => l && !l.startsWith('#'));
        const allJobs = [];
        lines.forEach((line) => {
          try {
            const job = parseQueueLine(line);
            if (job && job.prompt) {
              allJobs.push(job);
            }
          } catch (err) {
            // Ignore parse errors in preview
          }
        });
        const activeJobs = allJobs.filter(j => !j.disabled);
        return { all: allJobs, active: activeJobs };
      } catch {
        return { all: [], active: [] };
      }
    })(),
  ]);
  state.prompts = prompts;
  state.references = references;
  state.queueFileJobs = queueData.active;
  state.queueFileAllJobs = queueData.all;
  state.queueFileLoadedAt = new Date();
}

function setupWebServer(jobManager, telemetry, logger, state, port = 3000) {
  const app = express();
  app.use(cors());
  app.use(express.json());
  app.use(express.static(path.join(__dirname, 'public')));

  const clients = [];

  // SSE endpoint for real-time events
  app.get('/api/events', (req, res) => {
    res.setHeader('Content-Type', 'text/event-stream');
    res.setHeader('Cache-Control', 'no-cache');
    res.setHeader('Connection', 'keep-alive');

    const clientId = Date.now();
    clients.push({ id: clientId, res });

    const sendEvent = (type, data) => {
      res.write(`event: ${type}\ndata: ${JSON.stringify(data)}\n\n`);
    };

    sendEvent('connected', { clientId });

    const onJobEvent = (job) => sendEvent('job:update', job);
    const onBatchStart = (data) => sendEvent('batch:start', data);
    const onBatchSuccess = (data) => sendEvent('batch:success', data);
    const onBatchFailure = (data) => sendEvent('batch:failure', data);
    const onStatsUpdate = (stats) => sendEvent('stats:update', stats);
    const onQueueStart = (plan) => sendEvent('queue:start', plan);
    const onQueueUpdate = (plan) => sendEvent('queue:update', plan);
    const onQueueComplete = (data) => sendEvent('queue:complete', data);
    const onLogUpdate = (entry, entries) => sendEvent('log', entry);

    jobManager.on('job:queued', onJobEvent);
    jobManager.on('job:start', onJobEvent);
    jobManager.on('job:complete', onJobEvent);
    jobManager.on('batch:start', onBatchStart);
    jobManager.on('batch:success', onBatchSuccess);
    jobManager.on('batch:failure', onBatchFailure);
    jobManager.on('stats:update', onStatsUpdate);
    jobManager.on('queue:start', onQueueStart);
    jobManager.on('queue:update', onQueueUpdate);
    jobManager.on('queue:complete', onQueueComplete);
    logger.on('update', onLogUpdate);

    req.on('close', () => {
      const idx = clients.findIndex((c) => c.id === clientId);
      if (idx > -1) clients.splice(idx, 1);
      jobManager.removeListener('job:queued', onJobEvent);
      jobManager.removeListener('job:start', onJobEvent);
      jobManager.removeListener('job:complete', onJobEvent);
      jobManager.removeListener('batch:start', onBatchStart);
      jobManager.removeListener('batch:success', onBatchSuccess);
      jobManager.removeListener('batch:failure', onBatchFailure);
      jobManager.removeListener('stats:update', onStatsUpdate);
      jobManager.removeListener('queue:start', onQueueStart);
      jobManager.removeListener('queue:update', onQueueUpdate);
      jobManager.removeListener('queue:complete', onQueueComplete);
      logger.removeListener('update', onLogUpdate);
    });
  });

  // API endpoints
  app.get('/api/jobs', (req, res) => {
    const jobs = jobManager.getJobs().map((job) => ({
      id: job.id,
      source: job.source,
      promptName: job.promptName,
      state: job.state,
      createdAt: job.createdAt,
      startedAt: job.startedAt,
      finishedAt: job.finishedAt,
      stats: job.stats,
      lastError: job.lastError,
    }));
    res.json(jobs);
  });

  app.post('/api/jobs', (req, res) => {
    const { promptName, promptText, options, img2imgRefsPattern, autoRetry, targetImages } = req.body;
    if (!promptText) {
      return res.status(400).json({ error: 'promptText required' });
    }
    const job = jobManager.createJob({
      source: 'web',
      promptName: promptName || 'web-job',
      promptText,
      options: options || {},
      img2imgRefsPattern,
      autoRetry: Boolean(autoRetry),
      targetImages,
    });
    jobManager.enqueueJob(job);
    res.json({ id: job.id, message: 'Job queued' });
  });

  app.post('/api/jobs/:id/pause', (req, res) => {
    const success = jobManager.pauseJob(req.params.id);
    res.json({ success, message: success ? 'Job paused' : 'Job not found' });
  });

  app.post('/api/jobs/:id/resume', (req, res) => {
    const success = jobManager.resumeJob(req.params.id);
    res.json({ success, message: success ? 'Job resumed' : 'Job not found' });
  });

  app.post('/api/jobs/:id/cancel', (req, res) => {
    const success = jobManager.cancelJob(req.params.id);
    res.json({ success, message: success ? 'Job cancelled' : 'Job not found' });
  });

  app.delete('/api/jobs/:id', (req, res) => {
    const success = jobManager.removeJob(req.params.id);
    res.json({ success, message: success ? 'Job removed' : 'Job not found' });
  });

  app.get('/api/stats', (req, res) => {
    res.json({
      globalStats: jobManager.globalStats,
      requestStats: jobManager.getRequestStats(),
    });
  });

  app.get('/api/telemetry', (req, res) => {
    res.json({
      prompts: telemetry.getPromptStats(),
      references: telemetry.getReferenceStats(),
    });
  });

  app.get('/api/queue', (req, res) => {
    res.json({
      plan: jobManager.queuePlan,
      running: jobManager.queueRunState.running,
      activeJobIds: Array.from(jobManager.queueActiveJobIds),
    });
  });

  app.post('/api/queue/start', (req, res) => {
    jobManager.startQueue();
    res.json({ message: 'Queue started' });
  });

  app.post('/api/queue/stop', (req, res) => {
    jobManager.cancelAllRequests().then(() => {
      res.json({ message: 'Queue stopped' });
    });
  });

  app.post('/api/cancel-all', async (req, res) => {
    await jobManager.cancelAllRequests();
    res.json({ message: 'All requests cancelled' });
  });

  app.get('/api/assets', async (req, res) => {
    const [prompts, references] = await Promise.all([listPrompts(), listImg2ImgRefs()]);
    res.json({ prompts, references });
  });

  app.post('/api/assets/refresh', async (req, res) => {
    await refreshAssets(state, logger);
    res.json({ message: 'Assets refreshed' });
  });

  app.listen(port, () => {
    logger.info(`Web server running on http://localhost:${port}`);
  });
}

async function main() {
  try {
  const logger = new UILogger();
  const telemetry = new TelemetryStore();
  const jobManager = new JobManager(telemetry, logger);
  const state = {
    prompts: [],
    references: [],
    queueFileJobs: [],
    queueFileAllJobs: [],
    queueFileLoadedAt: null,
  };

  await ensureDirectories(logger);
  await refreshAssets(state, logger);

  // Start web server
  setupWebServer(jobManager, telemetry, logger, state, 3000);

  const screen = blessed.screen({ smartCSR: true, title: 'Nano Diffusion Control Center' });
  screen.key(['C-c'], () => {
    screen.destroy();
    process.exit(0);
  });

  let renderQueued = false;
  const scheduleRender = () => {
    if (renderQueued) return;
    renderQueued = true;
    setImmediate(() => {
      renderQueued = false;
      screen.render();
    });
  };

  const tabBar = blessed.box({
    parent: screen,
    top: 0,
    left: 0,
    width: '100%',
    height: 1,
    tags: true,
    style: { fg: 'white', bg: 'blue' },
  });

  const contentArea = blessed.box({
    parent: screen,
    top: 1,
    left: 0,
    right: 0,
    bottom: 1,
    style: { bg: 'black' },
  });

  const footer = blessed.box({
    parent: screen,
    bottom: 0,
    left: 0,
    width: '100%',
    height: 3,
    tags: true,
    style: { fg: 'black', bg: 'white' },
  });

  const sanitizeForBlessed = (value) => {
    if (value === null || value === undefined) return '';
    return String(value);
  };

  const stylizeStatus = (status) => {
    const map = {
      queued: '{blue-fg}QUEUED{/blue-fg}',
      running: '{yellow-fg}RUNNING{/yellow-fg}',
      completed: '{green-fg}DONE{/green-fg}',
      failed: '{red-fg}FAILED{/red-fg}',
    };
    if (!status) return '{gray-fg}UNKNOWN{/gray-fg}';
    return map[status] || sanitizeForBlessed(status).toUpperCase();
  };

  const buildDashboardTab = () => {
    const container = blessed.box({
      parent: contentArea,
      top: 0,
      left: 0,
      width: '100%',
      height: '100%',
      keys: true,
      mouse: true,
      scrollable: true,
      tags: true,
    });

    const summaryBox = blessed.box({
      parent: container,
      top: 0,
      left: 0,
      width: '100%',
      height: '35%',
      label: ' Overview ',
      border: 'line',
      tags: true,
      scrollable: true,
    });

    const jobTable = blessed.listtable({
      parent: container,
      top: '35%',
      left: 0,
      width: '100%',
      height: '35%',
      label: ' Jobs ',
      border: 'line',
      tags: true,
      interactive: false,
      mouse: true,
      scrollbar: { ch: ' ', track: { bg: 'grey' }, style: { inverse: true } },
    });

    const activeBox = blessed.box({
      parent: container,
      top: '70%',
      left: 0,
      width: '100%',
      height: '30%',
      label: ' Active Jobs ',
      border: 'line',
      tags: true,
      scrollable: true,
      alwaysScroll: true,
    });

    return {
      key: 'dashboard',
      title: 'Dashboard',
      container,
      render() {
        const stats = jobManager.globalStats;
        const requestStats = jobManager.getRequestStats();
        const uptime = Date.now() - stats.startedAt;
        try {
          summaryBox.setContent(
            [
              `{bold}Jobs{/bold}`,
              `  Total: ${stats.totalJobs || 0} | Completed: ${stats.completedJobs || 0} | Failed: ${stats.failedJobs || 0} | Running: ${stats.runningJobs || 0}`,
              `  Batches: ${stats.totalBatches || 0} (✅ ${stats.successfulBatches || 0} / ❌ ${stats.failedBatches || 0})`,
              `  Images generated: ${stats.totalImages || 0}`,
              `  Uptime: ${formatDuration(uptime)}`,
              '',
              `{bold}API Requests{/bold}`,
              `  Live: {yellow-fg}${requestStats.live}{/yellow-fg} | Queued: ${requestStats.queued} | Total: ${requestStats.total}`,
              jobManager.cancelRequested ? `  {red-fg}⚠ CANCELLATION IN PROGRESS{/red-fg}` : '',
              '',
              `{bold}Queue{/bold}`,
              jobManager.queueRunState.running
                ? `  Running (${jobManager.queueActiveJobIds.size || 0} remaining)`
                : '  Idle',
              '',
            ].filter(line => line !== null && line !== undefined && line !== '').map(sanitizeForBlessed).join('\n')
          );
        } catch (err) {
          console.error('Error setting summaryBox content:', err);
        }

        const jobs = jobManager.getJobs().slice(-18).reverse();
        const data = [
          ['ID', 'Source', 'Prompt', 'Status', 'Batches', 'Images', 'Last'],
          ...jobs.filter(job => job && job.stats).map((job) => [
            String(job.id || 'Unknown'),
            String(job.source || 'Unknown'),
            String(job.promptName || 'Unknown'),
            stylizeStatus(job.state || 'queued'),
            `${job.stats.successfulBatches || 0}✅ / ${job.stats.failedBatches || 0}❌`,
            `${job.stats.totalImages || 0}`,
            job.lastError ? `{red-fg}${String(job.lastError.message || job.lastError || 'Unknown error')}{/red-fg}` : '—',
          ].filter(val => val !== null && val !== undefined).map(val => String(val))),
        ];
        try {
          jobTable.setData(data);
        } catch (err) {
          console.error('Error setting jobTable data:', err);
        }

        const activeJobs = Array.from(jobManager.currentJobs)
          .map(jobId => jobManager.jobs.get(jobId))
          .filter(job => job && job.state === 'running');

        if (activeJobs.length === 0) {
          activeBox.setContent('No active jobs.');
        } else {
          const content = activeJobs.map((activeJob) => {
            const elapsed = activeJob.startedAt ? formatDuration(Date.now() - activeJob.startedAt) : '0s';
            const lastBatch = activeJob.stats.lastBatch;
            return [
              `{bold}${sanitizeForBlessed(activeJob.promptName || 'Unknown')}{/bold} (${sanitizeForBlessed(activeJob.id || 'Unknown')})`,
              `  Elapsed: ${elapsed} | Batches: ${activeJob.stats.successfulBatches || 0}✅/${activeJob.stats.failedBatches || 0}❌ | Images: ${activeJob.stats.totalImages || 0}`,
              lastBatch && lastBatch.status === 'failure' && lastBatch.error
                ? `  {red-fg}Last error: ${sanitizeForBlessed((lastBatch.error.message || lastBatch.error || 'Unknown error').slice(0, 60))}{/red-fg}`
                : '',
              ''
            ].filter(line => line !== null && line !== undefined && line !== '').join('\n');
          }).join('\n');

          try {
            activeBox.setContent(content);
          } catch (err) {
            console.error('Error setting activeBox content:', err);
          }
        }
      },
    };
  };

  const buildQueueTab = () => {
    const container = blessed.box({
      parent: contentArea,
      top: 0,
      left: 0,
      width: '100%',
      height: '100%',
      keys: true,
      mouse: true,
      scrollable: true,
      tags: true,
    });

    const planTable = blessed.listtable({
      parent: container,
      top: 0,
      left: 0,
      width: '100%',
      height: '60%',
      label: ' Queue Plan ',
      border: 'line',
      tags: true,
      interactive: true,
      keys: true,
      mouse: true,
      scrollable: true,
      scrollbar: { ch: ' ', track: { bg: 'grey' }, style: { inverse: true } },
    });

    const queueInfoBox = blessed.box({
      parent: container,
      top: '60%',
      left: 0,
      width: '100%',
      height: '20%',
      label: ' Queue Status ',
      border: 'line',
      tags: true,
      scrollable: true,
    });

    const queueFileBox = blessed.box({
      parent: container,
      top: '80%',
      left: 0,
      width: '100%',
      height: '20%',
      label: ' queue.txt Preview ',
      border: 'line',
      tags: true,
      scrollable: true,
      alwaysScroll: true,
    });

    return {
      key: 'queue',
      title: 'Queue',
      container,
      render() {
        const plan = jobManager.queuePlan
          ? jobManager.queuePlan
          : state.queueFileJobs.map((cfg, idx) => ({
              index: idx + 1,
              prompt: cfg.prompt || 'unknown',
              status: 'pending',
              jobId: null,
              config: cfg || {},
              result: null,
            }));

        const planData = [
          ['#', 'Prompt', 'Status', 'Progress', 'Model', 'Refs'],
          ...plan.filter(entry => entry).map((entry) => {
            const numImages = (entry.config && entry.config.numImages) || 0;
            const numBatches = (entry.config && entry.config.numBatches) || 0;
            const expectedTotal = numImages * numBatches;

            let progressStr = '—';
            if (entry.jobId) {
              const job = jobManager.jobs.get(entry.jobId);
              if (job && job.stats) {
                const actual = job.stats.totalImages || 0;
                const percent = expectedTotal > 0 ? Math.round((actual / expectedTotal) * 100) : 0;
                progressStr = `${actual}/${expectedTotal} (${percent}%)`;
                if (job.state === 'completed' && actual < expectedTotal * 0.9) {
                  progressStr = `{yellow-fg}${progressStr}{/yellow-fg}`;
                } else if (job.state === 'failed') {
                  progressStr = `{red-fg}${progressStr}{/red-fg}`;
                }
              }
            }

            return [
              String(entry.index || 0),
              String(entry.prompt || 'Unknown'),
              stylizeStatus(entry.status || 'pending'),
              progressStr,
              String((entry.config && entry.config.model) || CONFIG.DEFAULT_MODEL),
              String((entry.config && entry.config.img2imgRefsPattern) || '—'),
            ].filter(val => val !== null && val !== undefined).map(val => String(val));
          }),
        ];
        try {
          planTable.setData(planData);
        } catch (err) {
          console.error('Error setting planTable data:', err);
        }

        const queueStatusLines = [
          `Queue file: ${CONFIG.QUEUE_FILE}`,
          `Last scan: ${
            state.queueFileLoadedAt ? state.queueFileLoadedAt.toLocaleString() : '—'
          }`,
          `Current: ${
            jobManager.queueRunState.running
              ? `{yellow-fg}running{/yellow-fg}`
              : '{green-fg}idle{/green-fg}'
          }`,
          jobManager.queueRunState.running
            ? `In-flight jobs: ${jobManager.queueActiveJobIds.size}`
            : '',
        ];
        try {
          queueInfoBox.setContent(queueStatusLines.filter(Boolean).map(s => String(s || '')).join('\n'));
        } catch (err) {
          console.error('Error setting queueInfoBox content:', err);
        }

        const queuePreview =
          state.queueFileAllJobs.length === 0
            ? '(queue.txt empty or unavailable)'
            : state.queueFileAllJobs
                .slice(0, 12)
                .map(
                  (cfg, idx) => {
                    const line = `${idx + 1}. [${String(cfg.prompt || 'unknown')}] [${cfg.width || 0}x${cfg.height || 0}] [${cfg.numImages || 0}] [${cfg.numBatches || 0}] [${String(cfg.model || 'unknown')}] [${String(cfg.img2imgRefsPattern || 'none')}]`;
                    return cfg.disabled ? `{gray-fg}${line} (DISABLED){/gray-fg}` : line;
                  }
                )
                .join('\n');
        try {
          queueFileBox.setContent(String(queuePreview || ''));
        } catch (err) {
          console.error('Error setting queueFileBox content:', err);
        }
      },
    };
  };

  const buildTelemetryTab = () => {
    const container = blessed.box({
      parent: contentArea,
      top: 0,
      left: 0,
      width: '100%',
      height: '100%',
      keys: true,
      mouse: true,
      scrollable: true,
      tags: true,
    });

    const promptTable = blessed.listtable({
      parent: container,
      top: 0,
      left: 0,
      width: '50%',
      height: '70%',
      label: ' Prompt Health ',
      border: 'line',
      tags: true,
      interactive: false,
      mouse: true,
      scrollbar: { ch: ' ', track: { bg: 'grey' }, style: { inverse: true } },
    });

    const refTable = blessed.listtable({
      parent: container,
      top: 0,
      left: '50%',
      width: '50%',
      height: '70%',
      label: ' Reference Health ',
      border: 'line',
      tags: true,
      interactive: false,
      mouse: true,
      scrollbar: { ch: ' ', track: { bg: 'grey' }, style: { inverse: true } },
    });

    const assetsBox = blessed.box({
      parent: container,
      top: '70%',
      left: 0,
      width: '100%',
      height: '30%',
      label: ' Assets ',
      border: 'line',
      tags: true,
      scrollable: true,
      alwaysScroll: true,
    });

    return {
      key: 'telemetry',
      title: 'Telemetry',
      container,
      render() {
        const promptStats = telemetry.getPromptStats().slice(0, 20);
        const refStats = telemetry.getReferenceStats().slice(0, 20);
        try {
          promptTable.setData([
            ['Prompt', '✅', '❌', 'Fail %', 'Last error'],
            ...promptStats.filter(stat => stat).map((stat) => [
              String(stat.name || 'Unknown'),
              `${stat.success || 0}`,
              stat.failure > 0 ? `{red-fg}${stat.failure}{/red-fg}` : '0',
              stat.total ? formatPercent(stat.failRate) : '0%',
              stat.lastError ? `{red-fg}${String(stat.lastError || 'Unknown error')}{/red-fg}` : '',
            ].filter(val => val !== null && val !== undefined).map(val => String(val))),
          ]);
        } catch (err) {
          console.error('Error setting promptTable data:', err);
        }
        try {
          refTable.setData([
            ['Reference', '✅', '❌', 'Fail %', 'Last error'],
            ...refStats.filter(stat => stat).map((stat) => [
              String(stat.name || 'Unknown'),
              `${stat.success || 0}`,
              stat.failure > 0 ? `{red-fg}${stat.failure}{/red-fg}` : '0',
              stat.total ? formatPercent(stat.failRate) : '0%',
              stat.lastError ? `{red-fg}${String(stat.lastError || 'Unknown error')}{/red-fg}` : '—',
            ].filter(val => val !== null && val !== undefined).map(val => String(val))),
          ]);
        } catch (err) {
          console.error('Error setting refTable data:', err);
        }
        assetsBox.setContent(
          [
            `{bold}Prompts (${state.prompts.length}){/bold}`,
            state.prompts.length
              ? state.prompts.slice(0, 40).map((p) => `  • ${p}`).join('\n')
              : '  (none)',
            '',
            `{bold}Img2Img References (${state.references.length}){/bold}`,
            state.references.length
              ? state.references.slice(0, 40).map((r) => `  • ${r}`).join('\n')
              : '  (none)',
          ].join('\n')
        );
      },
    };
  };

  const buildLogsTab = () => {
    const container = blessed.box({
      parent: contentArea,
      top: 0,
      left: 0,
      width: '100%',
      height: '100%',
      keys: true,
      mouse: true,
      scrollable: true,
      tags: true,
    });
    const logBox = blessed.log({
      parent: container,
      top: 0,
      left: 0,
      width: '100%',
      height: '100%',
      label: ' Event Log ',
      border: 'line',
      tags: true,
      mouse: true,
      keys: true,
      scrollbar: { ch: ' ', track: { bg: 'grey' }, style: { inverse: true } },
    });

    logger.on('update', (entry) => {
      const ts = entry.timestamp ? entry.timestamp.toLocaleTimeString() : 'N/A';
      let prefix = `[${ts}]`;
      if (entry.level === 'warn') prefix = `{yellow-fg}${prefix}{/yellow-fg}`;
      else if (entry.level === 'error') prefix = `{red-fg}${prefix}{/red-fg}`;
      logBox.add(`${prefix} ${String(entry.message || '')}`);
      scheduleRender();
    });

    return {
      key: 'logs',
      title: 'Logs',
      container,
      render() {},
    };
  };

  const tabs = [
    buildDashboardTab(),
    buildQueueTab(),
    buildTelemetryTab(),
    buildLogsTab(),
  ];

  tabs.forEach((tab) => {
    tab.container.hide();
  });

  const tabManager = {
    activeIndex: 0,
    setActive(index) {
      if (index < 0 || index >= tabs.length) return;
      tabs[this.activeIndex].container.hide();
      this.activeIndex = index;
      tabs[this.activeIndex].container.show();
      tabs[this.activeIndex].render();
      updateTabBar();
      scheduleRender();
    },
    next() {
      this.setActive((this.activeIndex + 1) % tabs.length);
    },
    prev() {
      this.setActive((this.activeIndex - 1 + tabs.length) % tabs.length);
    },
  };

  const updateTabBar = () => {
    const label = tabs
      .map((tab, idx) => {
        const prefix = `${idx + 1}. ${tab.title}`;
        return idx === tabManager.activeIndex
          ? `{inverse} ${prefix} {/inverse}`
          : ` ${prefix} `;
      })
      .join(' ');
    tabBar.setContent(label);
  };

  const updateFooter = () => {
    const stats = jobManager.globalStats;
    const requestStats = jobManager.getRequestStats();
    const queueStatus = jobManager.queueRunState.running
      ? `{yellow-fg}Queue: running (${jobManager.queueActiveJobIds.size} remaining){/yellow-fg}`
      : '{green-fg}Queue: idle{/green-fg}';
    footer.setContent(
      `{bold}[←/→]{/bold} Tabs  {bold}[1-${tabs.length}]{/bold} Jump  {bold}[n]{/bold} New Job  {bold}[Ctrl+Q]{/bold} Run queue  {bold}[Ctrl+X]{/bold} Cancel  {bold}[r]{/bold} Refresh  {bold}[Ctrl+C]{/bold} Exit | Jobs: ${stats.totalJobs}/${stats.completedJobs}✓/${stats.failedJobs}✖ | API: {yellow-fg}${requestStats.live} live{/yellow-fg} / ${requestStats.queued} queued | Images: ${stats.totalImages} | ${queueStatus}`
    );
  };

  tabManager.setActive(0);
  updateFooter();

  const askInput = (title, initial = '') =>
    new Promise((resolve) => {
      const prompt = blessed.prompt({
        parent: screen,
        top: 'center',
        left: 'center',
        width: '60%',
        height: 'shrink',
        label: ` ${title} `,
        border: 'line',
        keys: true,
        mouse: true,
        tags: true,
      });
      prompt.input(initial, (err, value) => {
        prompt.destroy();
        scheduleRender();
        if (err) resolve(null);
        else resolve(value);
      });
      screen.render();
    });

  const askMultiline = (title, initial = '') =>
    new Promise((resolve) => {
      const box = blessed.box({
        parent: screen,
        top: 'center',
        left: 'center',
        width: '80%',
        height: '70%',
        border: 'line',
        label: ` ${title} `,
        keys: true,
        mouse: true,
        tags: true,
      });
      const instructions = blessed.box({
        parent: box,
        bottom: 0,
        left: 1,
        right: 1,
        height: 1,
        tags: true,
        content: '{bold}Ctrl+S{/bold} save | {bold}Esc{/bold} cancel',
      });
      const textarea = blessed.textarea({
        parent: box,
        top: 1,
        left: 1,
        right: 1,
        bottom: 1,
        keys: true,
        mouse: true,
        scrollbar: { ch: ' ', track: { bg: 'grey' }, style: { inverse: true } },
        border: 'line',
        inputOnFocus: true,
        value: initial,
      });
      textarea.focus();
      screen.render();
      const cleanup = (value) => {
        textarea.destroy();
        instructions.destroy();
        box.destroy();
        scheduleRender();
        resolve(value);
      };
      box.key(['escape'], () => cleanup(null));
      textarea.key(['C-s'], () => cleanup(textarea.getValue()));
    });

  let wizardOpen = false;
  const openNewJobWizard = async () => {
    if (wizardOpen) return;
    wizardOpen = true;
    try {
      logger.info('Launching interactive job wizard…');
      const promptNameInput = await askInput('Prompt name (existing) or leave blank for custom', '');
      let promptText;
      let promptName = promptNameInput ? promptNameInput.trim() : '';
      if (!promptName) {
        const customPrompt = await askMultiline('Enter prompt text', '');
        if (!customPrompt) {
          logger.warn('Interactive job cancelled (no prompt).');
          return;
        }
        promptText = customPrompt.trim();
        promptName = 'custom';
      } else {
        try {
          promptText = await loadPrompt(promptName);
          logger.info(`Loaded prompt "${promptName}".`);
        } catch (error) {
          logger.warn(error.message);
          const customPrompt = await askMultiline(`Prompt "${promptName}" not found. Enter prompt text`, '');
          if (!customPrompt) {
            logger.warn('Interactive job cancelled (missing prompt text).');
            return;
          }
          promptText = customPrompt.trim();
        }
      }

      const referencesInput = await askInput(
        'Img2Img references (comma separated, wildcards allowed, blank to skip)',
        ''
      );

      const widthInput = await askInput(`Width [${CONFIG.DEFAULT_WIDTH}]`, '');
      const heightInput = await askInput(`Height [${CONFIG.DEFAULT_HEIGHT}]`, '');
      const imagesInput = await askInput(`Images per batch [${CONFIG.DEFAULT_IMAGES}]`, '');
      const width = parseInt(widthInput, 10) || CONFIG.DEFAULT_WIDTH;
      const height = parseInt(heightInput, 10) || CONFIG.DEFAULT_HEIGHT;
      const numImages = parseInt(imagesInput, 10) || CONFIG.DEFAULT_IMAGES;

      const modeInput = (await askInput('Mode (b = fixed batches, t = target images) [b]', '')) || 'b';
      const mode = modeInput.trim().toLowerCase() || 'b';
      const autoRetry = mode === 't';

      let numBatches = CONFIG.DEFAULT_BATCHES;
      let targetImages = null;
      let tolerance = CONFIG.AUTO_RETRY_TOLERANCE;

      if (autoRetry) {
        const targetInput = await askInput(
          `Target total images [${numImages * CONFIG.DEFAULT_BATCHES}]`,
          ''
        );
        targetImages = parseInt(targetInput, 10) || numImages * CONFIG.DEFAULT_BATCHES;
        const toleranceInput = await askInput(
          `Tolerance (+/-) [${CONFIG.AUTO_RETRY_TOLERANCE}]`,
          ''
        );
        tolerance = parseInt(toleranceInput, 10) || CONFIG.AUTO_RETRY_TOLERANCE;
        numBatches = Math.ceil(targetImages / numImages);
      } else {
        const batchesInput = await askInput(`Number of batches [${CONFIG.DEFAULT_BATCHES}]`, '');
        numBatches = parseInt(batchesInput, 10) || CONFIG.DEFAULT_BATCHES;
      }

      const modelInput = await askInput(`Model [${CONFIG.DEFAULT_MODEL}]`, CONFIG.DEFAULT_MODEL);
      const model = modelInput ? modelInput.trim() : CONFIG.DEFAULT_MODEL;
      const styleInput = await askInput('Style (optional)', '');
      const style = styleInput ? styleInput.trim() : null;

      const job = jobManager.createJob({
        source: 'interactive',
        promptName,
        promptText,
        options: {
          width,
          height,
          numImages,
          numBatches,
          model,
          style,
        },
        img2imgRefsPattern: referencesInput ? referencesInput.trim() : null,
        autoRetry,
        targetImages: autoRetry ? targetImages : null,
        tolerance,
      });

      jobManager.enqueueJob(job);
      logger.info(`Interactive job queued: ${job.id} (${promptName})`);
      tabs[0].render();
      tabs[1].render();
      updateFooter();
      scheduleRender();
    } finally {
      wizardOpen = false;
    }
  };

  screen.key(['left'], () => tabManager.prev());
  screen.key(['right'], () => tabManager.next());
  screen.key(['1', '2', '3', '4'], (ch) => tabManager.setActive(parseInt(ch, 10) - 1));
  screen.key(['n'], () => openNewJobWizard());
  screen.key(['C-q'], () => {
    jobManager.startQueue();
  });
  screen.key(['C-x'], async () => {
    await jobManager.cancelAllRequests();
    tabs[0].render();
    updateFooter();
    scheduleRender();
  });
  screen.key(['r'], async () => {
    await refreshAssets(state, logger);
    tabs[1].render();
    tabs[2].render();
    scheduleRender();
    logger.info('Assets refreshed.');
  });

  jobManager.on('job:queued', () => {
    tabs[0].render();
    tabs[1].render();
    updateFooter();
    scheduleRender();
  });
  jobManager.on('job:start', () => {
    tabs[0].render();
    updateFooter();
    scheduleRender();
  });
  jobManager.on('job:complete', () => {
    tabs[0].render();
    tabs[1].render();
    updateFooter();
    scheduleRender();
  });
  jobManager.on('batch:start', () => {
    tabs[0].render();
    updateFooter();
    scheduleRender();
  });
  jobManager.on('batch:success', () => {
    tabs[0].render();
    tabs[2].render();
    updateFooter();
    scheduleRender();
  });
  jobManager.on('batch:failure', () => {
    tabs[0].render();
    tabs[2].render();
    updateFooter();
    scheduleRender();
  });
  jobManager.on('stats:update', () => {
    tabs[0].render();
    updateFooter();
    scheduleRender();
  });
  jobManager.on('queue:start', () => {
    tabs[1].render();
    updateFooter();
    scheduleRender();
  });
  jobManager.on('queue:update', () => {
    tabs[1].render();
    updateFooter();
    scheduleRender();
  });
  jobManager.on('queue:complete', () => {
    tabs[1].render();
    updateFooter();
    scheduleRender();
    logger.info('Queue complete.');
  });
  telemetry.on('update', () => {
    tabs[2].render();
    scheduleRender();
  });

  tabs.forEach((tab) => {
    try {
      tab.render();
    } catch (err) {
      console.error(`Error rendering tab ${tab.title}:`, err);
    }
  });
  updateTabBar();
  scheduleRender();
  logger.info('TUI ready.');
  } catch (err) {
    console.error('Error in main():', err);
    console.error('Stack:', err.stack);
    process.exit(1);
  }
}

main().catch((error) => {
  console.error('Fatal error:', error);
  process.exit(1);
